export function TechIcon({
  name,
  className = "w-4 h-4",
  size = 16,
  mono = false,
  color,
}: TechIconProps) {
  const normalizedKey = Object.keys(brandIcons).find(
    (k) => k.toLowerCase() === name.toLowerCase().trim()
  );

  const icon = normalizedKey ? brandIcons[normalizedKey] : null;

  if (!icon) {
    // Elegant fallback technical symbol
    return (
      <svg
        viewBox="0 0 24 24"
        className={className}
        width={size}
        height={size}
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-label={name}
      >
        <circle cx="12" cy="12" r="9" />
        <path d="M12 8v8M8 12h8" />
      </svg>
    );
  }

  const fill = color ? color : mono ? "currentColor" : `#${icon.hex}`;

  return (
    <svg
      role="img"
      viewBox="0 0 24 24"
      className={className}
      width={size}
      height={size}
      fill={fill}
      aria-label={icon.title || name}
    >
      <path d={icon.path} />
    </svg>
  );
}

export function TechBadge({
  name,
  label,
  className = "",
  iconClassName = "w-3.5 h-3.5",
  size = 14,
  mono = false,
}: TechBadgeProps) {
  const displayLabel = label || name;
  return (
    <span
      className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-white border border-[rgba(16,24,32,0.12)] text-xs font-mono font-semibold text-[#101820] shadow-2xs hover:border-[#004275]/40 transition-colors select-none ${className}`}
    >
      <TechIcon name={name} className={iconClassName} size={size} mono={mono} />
      <span>{displayLabel}</span>
    </span>
  );
}

export default TechIcon;
